import {Board} from './scene.js';
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeColor=value=>/^#[0-9a-f]{3,8}$/i.test(value||'')?value:'#b8a57c';
const sessionKey='jaffa-v3-seat';
const shortNames={p1:'卡特琳娜',p2:'莱拉',p3:'米哈伊尔',p4:'萨米尔'};
const abilityNames=['力量','敏捷','体质','智力','感知','魅力'];
const skillNames={acrobatics:'杂技',animalhandling:'驯兽',animalHandling:'驯兽',arcana:'奥秘',athletics:'运动',deception:'欺瞒',history:'历史',insight:'洞悉',intimidation:'威吓',investigation:'调查',medicine:'医药',nature:'自然',perception:'察觉',performance:'表演',persuasion:'游说',religion:'宗教',sleight:'巧手',stealth:'隐匿',survival:'求生'};
const spellNames={command:'命令术',createwater:'造水／毁水术',faith:'虔诚护盾',silence:'沉默术',acidsplash:'酸液飞溅',rayfrost:'冷冻射线',sleep:'睡眠术',web:'蛛网术',alarm:'警报术',unseen:'隐形仆役',scorching:'灼热射线',cure:'疗伤术',word:'治愈真言',missile:'魔法飞弹',bless:'祝福术',aid:'援助术',lesser:'次级复原术',sanctuary:'庇护术',shield:'护盾术',featherfall:'羽落术',magearmor:'法师护甲',shatter:'粉碎音波',guidance:'神导术',sacredflame:'圣火术',thaumaturgy:'奇术',light:'光亮术',spare:'维生术',magehand:'法师之手',detectmagic:'侦测魔法',comprehend:'通晓语言',mistystep:'迷踪步',minorillusion:'次级幻影'};
const numeric=(n,fallback=0)=>Number.isFinite(Number(n))?Number(n):fallback;
const signed=n=>(numeric(n)>=0?'+':'')+numeric(n);
const mod=n=>Math.floor((Number(n??10)-10)/2);
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
let token='',room=null,seat=null,state=null,settings={},pending=null,aiBusy=false,eventSeq=0,activeRoomId=null;
let selected='p1',target=null,mode='move',actions=[],tiles=[],busy=false,sideTab='character',logTab='story',requestCache=null,stream=null,streamGeneration=0,toastTimer,actionGeneration=0;
const party=()=>state?.actors?.filter(a=>a.side==='party')||[];
const unit=()=>state?.actors?.find(a=>a.id===selected)||party()[0];
const isDm=()=>!!(seat?.role==='dm'||seat?.isOwner);
const owns=id=>isDm()||seat?.actors?.includes(id);
const ownerOf=id=>room?.seats?.find(s=>s.id===room?.owners?.[id]);
const board=new Board($('board'),pickBoard);
function stored(key,fallback=null){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function saveStored(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{toast('浏览器未能保存席位；请在房间里保留自己的席位凭据。');}}
function toast(message){if($('gameShell').hidden){$('lobbyError').textContent=message;return;}$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,5500);}
function connection(ok,message){$('connection').textContent=message|| (ok?'已连接':'正在重连');$('connection').classList.toggle('offline',!ok);}
async function api(route,body,signal){const response=await fetch('/api/'+route,{method:body!==undefined?'POST':'GET',headers:{'Content-Type':'application/json',...(token?{'X-Seat-Token':token}:{}),...(room?.id?{'X-Room-Id':room.id}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{}),signal:signal||AbortSignal.timeout(20000),cache:'no-store'});let value;try{value=await response.json();}catch{throw Error('服务响应无法读取，请重试。');}if(!response.ok){if(value.state)await absorb(value);const error=Error(value.error||'操作未完成。');error.status=response.status;error.code=value.code;throw error;}return value;}
async function run(route,body={}){if(busy||!state)return null;busy=true;$('saveStatus').textContent='正在结算…';const payload={revision:state.revision,commandId:uid(),...body};try{let value;try{value=await api(route,payload);}catch(error){if(error instanceof TypeError||error.name==='TimeoutError'||error.name==='AbortError'){connection(false,'正在核对');value=await api(route,payload);}else throw error;}await absorb(value);$('saveStatus').textContent='已自动保存';return value;}catch(error){if(error.status===409)try{await absorb(await api('state'));}catch{}toast(error.message);$('saveStatus').textContent='进度已保留';return null;}finally{busy=false;}}
const cmd=command=>run('command',{command:Object.fromEntries(Object.entries(command).filter(([key])=>!['label','index','at'].includes(key)))});
async function absorb(value){if(!value?.state)return;if(state&&value.state.revision<state.revision)return;const oldCurrent=state?.current;const changed=!state||value.state.revision!==state.revision;state=value.state;state.gold=numeric(state.gold);for(const a of state.actors){for(const key of ['hp','maxHp','ac','level','tempHp','proficiency','speed','initiative','hitDie','hd','maxHd','potions','wind','maxWind','surge','maxSurge','channel','maxChannel','arcane','maxArcane','action','bonus','move','spellDC','spellAttack'])if(key in a)a[key]=numeric(a[key]);for(const key of ['abilities','saves','slots','maxSlots','death'])if(Array.isArray(a[key]))a[key]=a[key].map(n=>numeric(n));for(const w of a.weapons||[])for(const key of ['bonus','damageBonus','range','long'])if(key in w)w[key]=numeric(w[key]);}room=value.room||room;seat=value.seat||seat;settings=value.settings||settings;pending=value.pending??null;aiBusy=!!value.aiBusy;eventSeq=Math.max(eventSeq,value.eventSeq||0);if(!state.actors.some(a=>a.id===selected)||(!isDm()&&seat.actors?.length&&!seat.actors.includes(selected)))selected=seat.actors?.[0]||party()[0]?.id;if(state.current!==oldCurrent&&owns(state.current)&&state.actors.find(a=>a.id===state.current)?.side==='party')selected=state.current;if(target&&!state.actors.some(a=>a.id===target))target=null;render();if(changed)await loadActions();if($('modal').open&&$('modal').dataset.context==='room')showRoom();if($('modal').open&&$('modal').dataset.context==='ai')renderAiResult();}
async function loadActions(){if(!state)return;const generation=++actionGeneration,actor=selected,revision=state.revision;if(!owns(actor)){actions=[];tiles=[];renderActionBar();board.update(state,selected,tiles,target);return;}try{const [newActions,newTiles]=await Promise.all([api('actions?actor='+encodeURIComponent(actor)),api('reachable?actor='+encodeURIComponent(actor))]);if(generation!==actionGeneration||selected!==actor||state.revision!==revision)return;actions=Array.isArray(newActions)?newActions:[];tiles=Array.isArray(newTiles)?newTiles:[];renderActionBar();renderInspect();board.update(state,selected,tiles,target);}catch(error){if(generation!==actionGeneration)return;actions=[];tiles=[];board.update(state,selected,tiles,target);if(error.status!==403)toast(error.message);}}
function render(){if(!state)return;$('roomLabel').textContent=room?.name||'盐仓之夜';$('seatCount').textContent=(room?.seats?.filter(s=>s.online||s.id===seat.id).length||1)+' 席在线';$('sceneNumber').textContent='场景 '+String(state.chapter).padStart(2,'0')+' / 六景';$('sceneTitle').textContent=state.sceneData?.name||state.campaignView?.title||'雅法港';$('sceneMode').textContent=state.combat?'第 '+state.combat.round+' 轮 · 先攻':'探索';document.querySelectorAll('[data-dm]').forEach(el=>el.hidden=!isDm());document.querySelectorAll('[data-owner]').forEach(el=>el.hidden=!seat?.isOwner);renderChapters();renderStory();renderParty();renderActionBar();renderInspect();renderInitiative();renderSide();renderLog();board.mode=mode;board.update(state,selected,tiles,target);$('mapLegend').innerHTML='<span><i class="legend-dot"></i>可达格</span><span>拖动旋转 · 双指平移缩放</span>';}
function renderChapters(){const progress=state.campaignView?.chapters||[];$('chapterList').innerHTML=(state.chapters||[]).map((ch,i)=>{const p=progress.find(p=>p.number===i+1||p.id===ch.id);return `<button class="chapter-item ${i+1===state.chapter?'current':''}" data-chapter="${i+1}"><span class="number">${String(i+1).padStart(2,'0')}</span><span><strong>${esc(ch.title)}</strong><small>${i+1===state.chapter?'正在经历':p?.completed?'已收束':p?.visited?'已到访':'尚未到达'}</small></span></button>`;}).join('');$('chapterList').querySelectorAll('button').forEach(b=>b.onclick=()=>isDm()?showBook(+b.dataset.chapter):showChapterSummary(+b.dataset.chapter));}
function renderStory(){const cv=state.campaignView||{};$('objective').textContent=cv.description||'';$('storyEyebrow').textContent=cv.ended?'天亮以前 · 已收束':'眼前的事';$('objectiveList').innerHTML=(cv.objectives||[]).map(o=>`<div class="objective-row ${['done','complete','完成'].includes(o.status)?'done':''}"><span>${['done','complete','完成'].includes(o.status)?'◆':'◇'}</span>${esc(o.label)}</div>`).join('');const choices=state.choices||cv.options||[];$('choiceList').innerHTML=choices.map((ch,i)=>`<button data-choice="${i}" class="${/next|ending|close|finish/.test(ch.id)?'choice-next':''}" ${!owns(selected)?'disabled':''}>${esc(ch.label)}${ch.text?`<small>${esc(ch.text)}</small>`:''}</button>`).join('');$('choiceList').querySelectorAll('button').forEach(b=>b.onclick=()=>cmd({type:'choice',actor:selected,option:choices[+b.dataset.choice].id}));if(cv.ended&&!choices.length)$('choiceList').innerHTML='<button id="endingOpen" class="choice-next">阅读这一夜的结局 →</button>';if($('endingOpen'))$('endingOpen').onclick=()=>showJournal();}
function renderParty(){$('partyBar').innerHTML=party().map(a=>`<button class="party-card ${a.id===selected?'selected':''}" data-actor="${esc(a.id)}" style="--actor-color:${safeColor(a.color)}"><span class="party-avatar">${esc(a.portrait||a.name[0])}</span><span class="card-text"><strong>${esc(a.name)}</strong><small>${esc(a.role)} · ${a.level}级</small><div class="hp-track"><div class="hp-fill" style="width:${Math.max(0,Math.min(100,a.hp/a.maxHp*100))}%"></div></div><small>${a.dead?'已死亡':a.hp===0?'倒地 · '+(a.death||[]).join(' / '):'HP '+a.hp+'/'+a.maxHp+'　AC '+a.ac} · ${esc(ownerOf(a.id)?.name||'待认领')}</small></span></button>`).join('');$('partyBar').querySelectorAll('[data-actor]').forEach(b=>{b.onclick=()=>selectActor(b.dataset.actor);b.ondblclick=()=>showCharacter(b.dataset.actor);});}
function selectActor(id){selected=id;target=null;mode='move';sideTab='character';render();loadActions();}
function renderActionBar(){const a=unit();if(!a)return;const categories=[['move','⌖','移动'],['attack','⚔','攻击'],['spell','✦','施法'],['feature','◇','能力'],['item','♙','物品'],['interact','☷','交互']];$('actionBar').innerHTML=categories.map(([id,icon,label])=>`<button data-action="${id}" class="${mode===id?'active':''}" ${!owns(selected)?'disabled':''}><span class="action-icon">${icon}</span>${label}</button>`).join('')+(state.combat?`<button id="endTurn" class="primary" ${!owns(state.current)?'disabled':''}><span class="action-icon">⌛</span>结束回合</button>`:'');$('actionBar').querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{await loadActions();if(b.dataset.action==='move'){const openList=mode==='move';mode='move';board.mode=mode;renderActionBar();board.draw();if(openList||matchMedia('(pointer:coarse)').matches)showActions('move');else toast('点击高亮格移动；再次选移动可查看坐标列表。');return;}showActions(b.dataset.action);});if($('endTurn'))$('endTurn').onclick=()=>cmd({type:'end',actor:state.current});const current=state.actors.find(t=>t.id===state.current);$('turnStrip').innerHTML=state.combat?`<span class="current-turn">${esc(current?.name)}的回合</span><span>移动 ${a.move??0}尺</span><span>动作 ${a.action??0} · 附赠 ${a.bonus??0} · 反应 ${a.reaction?'●':'○'}</span>`:`<span>${esc(shortNames[a.id]||a.name)} · ${owns(a.id)?'可操作':'由 '+(ownerOf(a.id)?.name||'空席')+'控制'}</span><span>HP ${a.hp}/${a.maxHp} · AC ${a.ac}</span>`;}
function renderInitiative(){$('initiative').hidden=!state.combat;$('initiative').innerHTML=state.combat?state.combat.order.map(id=>{const a=state.actors.find(a=>a.id===id);return a?`<button data-target="${esc(id)}" class="${id===state.current?'current':''}">${esc(shortNames[id]||a.name)}</button>`:'';}).join(''):'';$('initiative').querySelectorAll('button').forEach(b=>b.onclick=()=>{target=b.dataset.target;renderInspect();board.update(state,selected,tiles,target);});}
function renderInspect(){const a=state.actors.find(a=>a.id===target);$('inspect').hidden=!a;if(!a)return;const valid=actions.filter(c=>c.target===a.id||c.targets?.includes(a.id));$('inspect').innerHTML=`<h3>${esc(a.name)}</h3><p>${a.hp!=null?'HP '+a.hp+'/'+a.maxHp+' · AC '+a.ac:a.down?'已失去行动能力':a.bloodied?'伤势明显':'仍有行动能力'}</p><p>${esc((a.conditions||[]).join(' · '))}</p><div class="button-row">${valid.length?'<button id="targetActions">对其行动</button>':''}<button id="targetCard">查看</button><button id="clearTarget" aria-label="取消目标">×</button></div>`;if($('targetActions'))$('targetActions').onclick=()=>showActions('target');$('targetCard').onclick=()=>showCharacter(a.id);$('clearTarget').onclick=()=>{target=null;renderInspect();board.update(state,selected,tiles,target);};}
async function pickBoard(p){if(!state||!p)return;if(p.actor){const a=state.actors.find(a=>a.id===p.actor);if(a.side==='party'&&mode!=='attack')selectActor(a.id);else{target=a.id;renderInspect();board.update(state,selected,tiles,target);if(mode==='attack')showActions('target');}return;}if(p.door!=null){return showDoors(p.door);}if(p.feature!=null){const f=state.sceneData.features[p.feature];if(p.inspect)return showFeature(f);const reachable=tiles.some(t=>t.x===p.x&&t.y===p.y&&t.cost>0);if(!reachable||!owns(selected))return showFeature(f);}if(mode==='move'&&owns(selected)){if(!tiles.some(t=>t.x===p.x&&t.y===p.y&&t.cost>0))return toast('此格当前不可到达。选择相邻高亮格，或查看交互位置。');await cmd({type:'move',actor:selected,x:p.x,y:p.y});}}
function setSide(tab,open=true){sideTab=tab;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));document.querySelectorAll('[data-mobile]').forEach(b=>b.classList.toggle('active',b.dataset.mobile===tab));document.body.classList.toggle('side-open',open);renderSide();}
function renderSide(){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===sideTab));if(sideTab==='character')renderCharacterPanel();else if(sideTab==='journal')renderJournalPanel();else renderTablePanel();}
function resourceRows(a){return [['熟练加值',signed(a.proficiency||2)],['速度',a.speed+'尺'],...(a.spellDC?[['法术攻击',signed(a.spellAttack)],['法术豁免 DC',a.spellDC]]:[]),['激励',a.inspiration?'●':'○'],['生命骰',(a.hd??0)+' / '+(a.maxHd??a.level)+' d'+(a.hitDie||8)],...((a.slots||[]).map((n,i)=>[(i+1)+'环法术位',n+' / '+(a.maxSlots?.[i]??0)])),...([['wind','maxWind','回气'],['surge','maxSurge','动作如潮'],['channel','maxChannel','引导神力'],['arcane','maxArcane','奥术回想']].filter(([k,m])=>a[m]||a[k]).map(([k,m,n])=>[n,(a[k]||0)+' / '+(a[m]||0)])),['治疗药水',a.potions||0]].map(([label,value])=>`<div><span>${esc(label)}</span><b>${esc(value)}</b></div>`).join('');}
function statGrid(a){return `<div class="stat-grid">${abilityNames.map((n,i)=>`<div>${n}<strong>${esc(a.abilities?.[i]??'—')}</strong><small>${signed(mod(a.abilities?.[i]))}</small></div>`).join('')}</div>`;}
function renderCharacterPanel(){const a=unit();if(!a)return;$('sideContent').innerHTML=`<section class="character-paper"><div class="character-title"><div class="character-medallion">${esc(a.portrait||a.name[0])}</div><div><h2>${esc(shortNames[a.id]||a.name)}</h2><p>${esc(a.role)} · ${a.level}级</p></div></div><div class="hp-header"><span>HP　${a.hp} / ${a.maxHp}${a.tempHp?' + '+a.tempHp+'临时':''}</span><span>AC　${a.ac}</span></div><div class="hp-track"><div class="hp-fill" style="width:${Math.max(0,Math.min(100,a.hp/a.maxHp*100))}%"></div></div>${statGrid(a)}<div class="button-row"><button id="fullCard">完整角色卡</button><button id="checkSkill">检定</button><button id="claimSelected" ${!owns(a.id)&&ownerOf(a.id)?'disabled':''}>${ownerOf(a.id)?.id===seat.id?'释放角色':owns(a.id)&&!ownerOf(a.id)?'领取角色':ownerOf(a.id)?'已领取':'领取角色'}</button></div><div class="resource-list">${resourceRows(a)}</div><div class="condition-tags">${[...(a.conditions||[]),...(a.prone?['倒地']:[]),...(a.dead?['已死亡']:[]),...(a.concentration?['专注：'+(spellNames[a.concentration.spell]||a.concentration.spell)]:[])].map(c=>`<span>${esc(c)}</span>`).join('')}</div><p class="owner-line"><span>${esc(ownerOf(a.id)?.name||'等待领取')}</span><span>${esc(a.class||'')} · ${esc(a.subclass||'')}</span></p></section>`;$('fullCard').onclick=()=>showCharacter(a.id);$('checkSkill').onclick=()=>showChecks(a.id);$('claimSelected').onclick=()=>run('seat',{actor:a.id,release:ownerOf(a.id)?.id===seat.id});}
function journalHtml(brief=false){const cv=state.campaignView||{},npcs=Object.values(cv.npcs||{}),items=Object.values(cv.items||{});const endings=[...(cv.ending?[cv.ending]:[]),...Object.values(cv.endings||{})];return (endings.length?endings.map(e=>`<article class="ending-card"><h3>${esc(e.title||e.name||e.id||'这一夜的结局')}</h3><p>${esc(e.text||e.description||e.ending||e.destination||e.status||'')}</p></article>`).join(''):'')+(npcs.length?'<h3>此夜相逢</h3>'+npcs.map(n=>`<div class="journal-entry"><h3>${esc(n.name)}</h3><p>${esc([n.status,n.attitude,n.location,n.safe?'已安全':'',n.dead?'已死亡':''].filter(Boolean).join(' · '))}</p></div>`).join(''):'')+(items.length?'<h3>物件与归属</h3>'+items.map(i=>`<div class="journal-entry"><h3>${esc(i.name)}</h3><p>${esc(shortNames[i.holder]||party().find(a=>a.id===i.holder)?.name||i.holder||'未持有')}${i.destroyed?' · 已毁':''}${i.count!=null?' · '+i.count+'件':''}${i.charges!=null?' · '+i.charges+'次':''}</p></div>`).join(''):'')+(cv.fireSources?.length?'<h3>火具与火绳</h3>'+cv.fireSources.map(f=>'<div class="journal-entry"><p>'+esc(f.label)+' · '+(f.resolved?'已处理':'尚未处理')+'</p></div>').join(''):'')+(cv.pending?.length?'<h3>仍需回应</h3>'+cv.pending.map(p=>'<p>'+esc(p)+'</p>').join(''):'')+(cv.promises?.length?'<h3>约定</h3>'+cv.promises.map(p=>`<p>${esc(p.text||p.label)} · ${esc(p.status)}</p>`).join(''):'')+(!brief?(state.journal||[]).map(j=>`<article class="journal-entry"><h3>${esc(j.title)}</h3><p>${esc(j.text)}</p></article>`).join(''):'');}
function renderJournalPanel(){$('sideContent').innerHTML='<section class="journal-paper">'+(journalHtml(true)||'<p class="empty-message">这一夜的见闻会留在这里。</p>')+'<div class="button-row"><button id="fullJournal">全部手记</button>'+(isDm()?'<button id="sideHandouts">发布手札</button>':'')+'</div></section>';$('fullJournal').onclick=()=>showJournal();if($('sideHandouts'))$('sideHandouts').onclick=()=>showHandouts();}
function renderTablePanel(){$('sideContent').innerHTML='<section class="table-card"><h3>'+esc(room.name)+'</h3>'+room.seats.map(s=>`<div class="seat-row"><strong>${esc(s.name)}<small>${s.role==='dm'?'主持':'玩家'} · ${esc(({human:'真人',workspace:'工作区 AI',api:'API AI'})[s.kind]||s.kind)}</small></strong><span>${s.online||s.id===seat.id?'在线':'离线'}</span></div>`).join('')+'<div class="button-row"><button id="sideRoom">席位与房间</button><button id="sideAI">AI 同行</button></div><p class="muted">'+(room.aiPaused?'API AI 已暂停':'API AI 已恢复')+'</p></section>';$('sideRoom').onclick=showRoom;$('sideAI').onclick=showAI;}
function renderLog(){const old=$('logPanel'),atBottom=old.scrollHeight-old.scrollTop-old.clientHeight<45;const list=(state.log||[]).filter(l=>logTab==='dice'?['dice','damage','heal','rule'].includes(l.kind):!['move','ai-note','dice'].includes(l.kind));old.innerHTML=list.slice(-80).map(l=>`<div class="log-entry ${['story','chat','damage','dice'].includes(l.kind)?l.kind:''}"><span class="label">${esc(({story:'行旅见闻',chat:'桌边交谈',choice:'选择',dice:'检定',damage:'伤害',heal:'恢复',rule:'规则结算',gm:'主持裁定',ai:'AI 同行'})[l.kind]||'记录')}${l.time?' · '+esc(new Date(l.time).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})):''}</span>${esc(l.text)}</div>`).join('');if(atBottom||old.dataset.initial!=='yes'){old.scrollTop=old.scrollHeight;old.dataset.initial='yes';}}
function modal(title,html,context=''){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('modal').dataset.context=context;if(!$('modal').open)$('modal').showModal();}
const close=()=>$('modal').close();
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copyText(value,message='已复制'){try{await navigator.clipboard.writeText(value);toast(message);}catch{modal('复制内容','<textarea id="manualCopy" rows="6" readonly></textarea>');$('manualCopy').value=value;$('manualCopy').select();}}
const actionGroups={move:['move'],attack:['attack'],spell:['spell','cast','prepare'],feature:['feature','wind','surge','dash','disengage','dodge','stand','stabilize','start','retreat'],item:['item','potion','rest','wait'],interact:['choice','door','rest','wait']};
async function showActions(category='feature'){if(!owns(selected))return showRoom();await loadActions();mode=category==='attack'?'attack':'move';board.mode=mode;board.draw();let list=actions.filter(c=>category==='target'?(c.target===target||c.targets?.includes(target)):(actionGroups[category]||[]).includes(c.type));const title=({move:'移动到达',attack:'攻击与目标',spell:'法术与准备',feature:'行动与能力',item:'物品与休整',interact:'场景交互',target:'对目标行动'})[category]||'可用行动';const a=unit();let html=`<p>${esc(shortNames[a.id]||a.name)} · ${state.combat?'动作 '+(a.action||0)+' / 附赠 '+(a.bonus||0):'探索中'}</p>`;if(category==='spell')html+='<p class="muted">'+((a.slots||[]).map((n,i)=>(i+1)+'环 '+n+'/'+(a.maxSlots?.[i]||0)).join(' · ')||'当前没有法术位')+'</p>';if(category==='attack')html+='<div class="form-grid"><label>目标掩护<select id="coverSelect"><option value="0">无遮蔽 · +0 AC</option><option value="2">半身掩护 · +2 AC</option><option value="5">四分之三掩护 · +5 AC</option></select></label><label class="row"><input type="checkbox" id="knockCheck">近战击昏</label></div>';const groups=new Map();for(const [i,c]of list.entries()){const key=c.type+':'+c.option+':'+(c.slot??'')+':'+(c.mode||'')+':'+(c.text||'');groups.set(key,[...(groups.get(key)||[]),{c,i}]);}html+='<div class="ability-groups">'+([...groups.values()].map(group=>group.length===1?`<button class="ability-command" data-legal="${group[0].i}">${esc(group[0].c.label||group[0].c.option||group[0].c.type)}</button>`:`<details ${category==='target'?'open':''}><summary>${esc((group[0].c.label||group[0].c.option||group[0].c.type).split(' · ')[0])} <small>${group.length}个选项</small></summary><div class="button-row">${group.map(({c,i})=>`<button data-legal="${i}">${esc(c.label||c.option||c.type)}</button>`).join('')}</div></details>`).join('')||'<p class="empty-message">当前没有这类可执行行动。回合、位置、资源或场景可能尚未满足。</p>')+'</div>';if(category==='interact')html+='<div class="button-row"><button id="openDoors">门与地图物件</button><button id="openChecks">自由检定</button></div>';modal(title,html);if($('coverSelect'))$('coverSelect').value=stored('jaffa-v3-cover',0);if($('knockCheck'))$('knockCheck').checked=stored('jaffa-v3-knock',false);$('modalBody').querySelectorAll('[data-legal]').forEach(b=>b.onclick=async()=>{const action={...list[+b.dataset.legal]};if(action.type==='attack'){action.cover=Number($('coverSelect')?.value??stored('jaffa-v3-cover',0));action.knock=$('knockCheck')?.checked??stored('jaffa-v3-knock',false);saveStored('jaffa-v3-cover',action.cover);saveStored('jaffa-v3-knock',action.knock);}if(await cmd(action))close();});if($('openDoors'))$('openDoors').onclick=()=>showDoors();if($('openChecks'))$('openChecks').onclick=()=>showChecks(selected);}
function showCharacter(id){const a=state.actors.find(a=>a.id===id);if(!a)return;if(a.side!=='party'&&!isDm())return modal(a.name,`<p>${a.down?'已失去行动能力':a.bloodied?'伤势明显':'仍有战斗力'}</p><p>${esc((a.conditions||[]).join(' · '))}</p>`);const spellList=keys=>(keys||[]).map(k=>spellNames[k]||k).join(' · ');modal(a.name,`<p class="eyebrow">${esc(a.role||a.source||'角色')} · ${a.level||'—'}级 · ${esc(a.subclass||'')}</p><p>${esc(a.bio||'')}</p>${statGrid(a)}<div class="button-row"><span class="tag">HP ${a.hp}/${a.maxHp}</span><span class="tag">AC ${a.ac}</span><span class="tag">先攻 ${signed(a.initiative||0)}${a.initiativeAdv?' · 优势':''}</span><span class="tag">${esc(a.armor||'')}</span></div><div class="resource-list">${resourceRows(a)}</div><h3>豁免</h3><div class="skill-grid">${abilityNames.map((n,i)=>`<button data-save="${i}" ${!owns(a.id)?'disabled':''}><span>${n}</span><b>${signed(a.saves?.[i]??mod(a.abilities?.[i])+(a.saveProficiencies?.includes(i)?a.proficiency||2:0))}</b></button>`).join('')}</div><h3>技能</h3><div class="skill-grid">${Object.entries(a.skills||{}).map(([key,value])=>`<button data-skill="${esc(key)}" ${!owns(a.id)?'disabled':''}><span>${esc(skillNames[key]||key)}</span><b>${signed(value)}</b></button>`).join('')}</div><h3>武器</h3>${(a.weapons||[]).map(w=>`<div class="journal-entry"><h3>${esc(w.name)} <small>命中 ${signed(w.bonus)}</small></h3><p>${esc(w.dice)}${signed(w.damageBonus)} ${esc(w.type)} · ${w.range}${w.long!==w.range?'/'+w.long:''}尺${w.mastery?' · '+esc(w.mastery):''}</p></div>`).join('')}<h3>特性</h3><p>${(a.features||[]).map(esc).join('<br>')}</p>${a.spells?.length?`<h3>法术</h3><p>戏法：${esc(spellList(a.cantrips))}</p><p>准备：${esc(spellList(a.prepared))}</p>${a.domainSpells?.length?`<p>领域法术：${esc(spellList(a.domainSpells))}</p>`:''}${Object.keys(a.magicInitiate||{}).length?`<p>魔法学徒：${Object.entries(a.magicInitiate).map(([k,n])=>esc(spellNames[k]||k)+' · 免费 '+esc(n)+'次').join('；')}</p>`:''}<p>仪式：${esc(spellList(a.ritualSpells))}</p>${a.spellbook?.length?`<details><summary>法术书</summary><p>${esc(spellList(a.spellbook))}</p></details>`:''}`:''}<h3>行装与语言</h3><p>${(a.inventory||[]).map(esc).join(' · ')||'—'}</p><p>语言：${(a.languages||[]).map(esc).join(' · ')||'—'}<br>工具：${(a.tools||[]).map(esc).join(' · ')||'—'}</p><div class="rule-note">${esc(a.manual||a.source||'')}</div>${isDm()&&(a.fullStatBlock||a.statBlockRef)?'<div class="button-row"><button class="primary" data-stat-card="'+esc(a.id)+'">完整战斗卡与官方原文 ↗</button></div>':''}<div class="button-row">${owns(a.id)?'<button id="cardActions" class="primary">使用能力</button>':''}${isDm()?'<button id="editThis">主持调整</button>':''}<button id="exportCard">导出角色卡</button></div>`);$('modalBody').querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>showChecks(id,'save',b.dataset.save));$('modalBody').querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>showChecks(id,'skill',b.dataset.skill));if($('cardActions'))$('cardActions').onclick=()=>{selected=id;showActions('feature');};if($('editThis'))$('editThis').onclick=()=>showGM(id);$('exportCard').onclick=()=>download(a.name+'-角色卡.json',JSON.stringify(a,null,2));}
async function showStatBlock(id){if(!isDm())return;const a=state.actors.find(a=>a.id===id);if(!a)return;const ref=a.statBlockRef||a.type;modal(a.name+' · 完整战斗卡','<p>正在读取完整原文…</p>');try{let block;if(['commoner','guard','bandit','odon','ember'].includes(ref))block=await api('statblock?type='+encodeURIComponent(ref));else block={text:typeof a.fullStatBlock==='string'?a.fullStatBlock:a.fullStatBlock?.text,originalText:a.originalStatBlock,originalName:a.originalStatBlockName,kind:a.statBlockKind,adaptations:a.statBlockAdaptations,source:a.sourceUrl||a.sourceName,pages:a.sourcePages,license:a.sourceLicense,licenseUrl:a.sourceLicenseUrl,attribution:a.sourceAttribution,runtimeNotice:a.statBlockNotice};const kind=({srd:'SRD 官方卡','adapted-srd':'SRD 原卡的本场改编',original:'本作原创'})[block.kind]||'本场卡片';let href='';try{const u=new URL(block.source);if(u.protocol==='https:'&&!u.username&&!u.password)href=u.href;}catch{}const pages=Array.isArray(block.pages)?block.pages.join('、'):block.pages;modal(a.name+' · 完整战斗卡',`<div class="stat-card-heading"><h3>${esc(a.name)}</h3><span class="stat-kind">${esc(kind)}</span></div><p>当前局面：HP ${a.hp} / ${a.maxHp} · AC ${a.ac} · ${esc((a.conditions||[]).join(' · ')||'无额外状态')}</p><div class="stat-notice">${esc(block.runtimeNotice||'以下为完整本场卡片与来源；当前伤势和已消耗资源以游戏局面为准。')}</div><h3>本场完整可用卡</h3><div class="book-text">${esc(block.text||'此角色没有独立的完整正文卡。')}</div>${block.adaptations?.length?'<h3>本场删改说明</h3><ul>'+block.adaptations.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>':''}${block.originalText?`<details class="original-stat-block"><summary>官方完整原文 · ${esc(block.originalName||'SRD 5.2.1')}</summary><div class="book-text">${esc(block.originalText)}</div></details>`:'<div class="stat-notice">这是本作原创生物，没有冒充的官方原卡。</div>'}<p class="stat-source"><strong>来源</strong>　${href?'<a href="'+esc(href)+'" target="_blank" rel="noopener noreferrer">'+esc(a.sourceName||block.originalName||'SRD 5.2.1 官方文档')+'</a>':esc(block.source||a.sourceName||'本作原创规则')} ${pages?' · '+esc(pages)+'页':''}<br>${esc(block.license||'')}<br>${esc(block.attribution||'')}</p><div class="button-row"><button id="copyStatBlock">复制本场完整卡</button><button id="backCharacter">返回角色</button></div>`);$('copyStatBlock').onclick=()=>copyText(block.text||'','已复制本场完整卡');$('backCharacter').onclick=()=>showCharacter(id);}catch(e){modal(a.name+' · 完整战斗卡','<p>'+esc(e.message)+'</p><button id="retryStatBlock">重新读取</button>');$('retryStatBlock').onclick=()=>showStatBlock(id);}}
document.addEventListener('click',e=>{const button=e.target.closest?.('[data-stat-card]');if(button)showStatBlock(button.dataset.statCard);});
function showChecks(id=selected,type='skill',option='perception'){const a=state.actors.find(a=>a.id===id);if(!owns(id))return showRoom();modal('检定与豁免',`<p>${esc(a.name)}</p><div class="form-grid"><label>检定类型<select id="checkType"><option value="skill">属性 / 技能检定</option><option value="save">豁免</option></select></label><label>难度 DC<input id="checkDC" type="number" min="1" max="40" value="13"></label><label class="full">项目<select id="checkOption"></select></label></div><button id="checkGo" class="primary">掷骰并记入同桌记录</button><div class="rule-note">自由检定记录结果；剧情选项会独立结算它要求的检定。</div>`);const refresh=()=>{$('checkOption').innerHTML=$('checkType').value==='save'?abilityNames.map((n,i)=>`<option value="${i}">${n}豁免</option>`).join(''):Object.entries(a.skills||{}).map(([k,v])=>`<option value="${esc(k)}">${esc(skillNames[k]||k)} ${signed(v)}</option>`).join('');};$('checkType').value=type;refresh();$('checkOption').value=option;$('checkType').onchange=refresh;$('checkGo').onclick=async()=>{if(await cmd({type:$('checkType').value,actor:id,option:$('checkOption').value,dc:Number($('checkDC').value)}))close();};}
function showFeature(f){if(!f)return;modal(f.label||'地图物件',`<p>位置（${f.x}, ${f.y}） · ${f.w} × ${f.h}尺${f.height_ft?' · 高 '+f.height_ft+'尺':''}${f.difficult?' · 困难地形':''}</p><button id="featureChoices" class="primary">查看当前交互</button>`);$('featureChoices').onclick=()=>showActions('interact');}
function showDoors(focus=null){const sc=state.sceneData;modal('门与地图物件',`<p>${esc(sc.name)} · ${sc.width_ft} × ${sc.height_ft}尺 · 每格 ${sc.grid_ft||5}尺</p><div class="rule-note">旋转、低墙与顶视只改变查看方式。未标高度的门扇与物件采用示意模型；OBJ保留正文已标墙高，1单位为1尺。</div><div class="ability-groups">${(sc.openings||[]).map((d,i)=>`<button class="ability-command" data-door="${i}" ${!owns(selected)?'disabled':''}>${esc(d.label||d.id||'门')} · ${esc(({open:'已打开',closed:'已关闭',locked:'上锁'})[state.doors?.[i]||d.state]||d.state)}<small>　${d.a.join(',')} → ${d.b.join(',')}</small></button>`).join('')}</div><h3>地形与物件</h3>${(sc.features||[]).map((f,i)=>`<button class="ability-command" data-feature="${i}">${esc(f.label||f.kind)}<small>　(${f.x},${f.y}) · ${f.w}×${f.h}尺${f.height_ft?' · 高'+f.height_ft+'尺':''}</small></button>`).join('')}${isDm()&&sc.notes?.length?'<div class="rule-note">'+sc.notes.map(esc).join('\n')+'</div>':''}`);$('modalBody').querySelectorAll('[data-door]').forEach(b=>b.onclick=async()=>{if(await cmd({type:'door',actor:selected,option:b.dataset.door}))showDoors();});$('modalBody').querySelectorAll('[data-feature]').forEach(b=>b.onclick=()=>showFeature(sc.features[+b.dataset.feature]));if(focus!==null)$('modalBody').querySelector(`[data-door="${focus}"]`)?.focus();}
function showChapterSummary(number){const ch=state.chapters[number-1];modal(ch.title,`<p>${number===state.chapter?'你们正在经历这一景。':'依照这一夜已经发生的事，继续眼前的选择。'}</p><p>固定四人三级 · 六景短篇</p>`);}
function showJournal(){modal('这一夜的手记',journalHtml()+'<h3>队伍行囊</h3><p>'+esc((state.inventory||[]).join(' · '))+'</p><p>队伍资金 '+(state.gold||0)+' GP</p><div class="button-row">'+(isDm()?'<button id="journalHandouts">逐件手札</button>':'')+'</div><label>记下约定或行动<textarea id="noteText" rows="3" maxlength="5000"></textarea></label><button id="noteSave" class="primary" '+(!owns(selected)?'disabled':'')+'>记入手记</button>');$('noteSave').onclick=async()=>{const text=$('noteText').value.trim();if(text&&await cmd({type:'note',actor:selected,text}))showJournal();};if($('journalHandouts'))$('journalHandouts').onclick=()=>showHandouts();}
async function showBook(chapter=state.chapter){if(!isDm())return;modal('主持书 · 雅法余烬',`<label>场景<select id="bookSelect">${state.chapters.map((ch,i)=>`<option value="${i+1}" ${i+1===chapter?'selected':''}>${String(i+1).padStart(2,'0')} ${esc(ch.title)}</option>`).join('')}</select></label><div class="button-row"><button id="copyChapter">复制正文</button><button id="bookHandouts">逐件手札</button><button id="jumpChapter">主持跳转</button></div><div id="bookText" class="book-text">正在读取正文…</div>`);$('bookSelect').onchange=e=>showBook(+e.target.value);$('bookHandouts').onclick=()=>showHandouts(chapter);$('jumpChapter').onclick=()=>{modal('主持跳转',`<p>跳转到 ${esc(state.chapters[chapter-1].title)}。</p><label>裁定原因<textarea id="jumpReason" rows="3"></textarea></label><button id="jumpGo" class="primary">写入原因并跳转</button>`);$('jumpGo').onclick=async()=>{if(await cmd({type:'gm',actor:selected,text:$('jumpReason').value,patch:{chapter}}))close();};};try{const ch=await api('chapter?id='+chapter);if(!$('bookText'))return;$('bookText').textContent=ch.text||'本景正文尚未载入。';$('copyChapter').onclick=()=>copyText(ch.text||'','已复制本景正文');}catch(e){toast(e.message);}}
async function showHandouts(){if(!isDm())return;try{const list=await api('handouts');let selectedHandout=list[0];const cues={H01:'岸边听清路线后',H02:'查看炉间冷座后',H03:'调查陶匠工具或拒售主张后',H04:'实际查看水道干台短便条后',H05:'天亮交接开始点名与协商时',H06:'可开场公开的桌边速查'};modal('逐件手札',`<label>材料<select id="handoutPick">${list.map(h=>`<option value="${esc(h.id)}">${esc(h.id)} · ${esc(h.title)}</option>`).join('')}</select></label><p id="handoutCue" class="muted"></p><pre id="handoutText" class="handout-text"></pre><div class="button-row"><button id="handoutPublish" class="primary">发给本桌</button><button id="handoutCopy">复制正文</button></div>`);const draw=()=>{selectedHandout=list.find(h=>h.id===$('handoutPick').value);$('handoutCue').textContent=selectedHandout?.cue||cues[selectedHandout?.id]||'';$('handoutText').textContent=selectedHandout?.text||'';$('handoutPublish').disabled=!selectedHandout||(state.journal||[]).some(j=>j.sourceHandout===selectedHandout.id);};$('handoutPick').onchange=draw;$('handoutPublish').onclick=async()=>{if(await cmd({type:'handout',option:selectedHandout.id}))draw();};$('handoutCopy').onclick=()=>copyText(selectedHandout?.text||'','已复制手札正文');draw();}catch(e){toast(e.message);}}
function showRoom(){if(!room)return;const owner=seat.isOwner;modal(room.name,`<h3>席位与角色</h3><div class="claim-grid">${party().map(a=>{const member=ownerOf(a.id);return `<div class="claim-card"><span class="party-avatar" style="--actor-color:${safeColor(a.color)}">${esc(a.portrait||a.name[0])}</span><h3>${esc(shortNames[a.id]||a.name)}</h3><small>${esc(member?.name||'等待领取')}</small><button data-claim="${esc(a.id)}" ${member&&member.id!==seat.id&&!isDm()?'disabled':''}>${member?.id===seat.id?'释放角色':member?'接管角色':'领取角色'}</button>${isDm()?`<select data-assign="${esc(a.id)}" aria-label="${esc(a.name)}的席位"><option value="">等待领取</option>${room.seats.map(s=>`<option value="${esc(s.id)}" ${room.owners?.[a.id]===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select>`:''}</div>`;}).join('')}</div><h3>同桌的人</h3><div class="seat-list">${room.seats.map(s=>`<div class="seat-row"><strong>${esc(s.name)}<small>${s.role==='dm'?'主持':'玩家'} · ${esc(({human:'真人',workspace:'工作区 AI',api:'API AI'})[s.kind]||s.kind)}</small></strong><span>${s.online||s.id===seat.id?'在线':s.presence==='connected'?'工作区已连接':'离线'}</span>${owner?`<button data-dm-seat="${esc(s.id)}">设为主持</button>${s.kind==='api'?`<button data-api-run="${esc(s.id)}">启动 API</button>`:''}${s.kind!=='human'?`<button data-take="${esc(s.id)}">真人接管</button>`:''}${s.id!==room.ownerId?`<button data-remove="${esc(s.id)}">移出席位</button>`:''}`:''}</div>`).join('')}</div>${owner?`<div class="button-row"><button id="copyInvite" class="primary">复制邀请链接</button><button id="rotateInvite">更换邀请</button><button id="createAiSeat">新增 AI 席位</button><button id="pauseAi">${room.aiPaused?'恢复 API AI':'暂停全部 AI'}</button></div><label class="row"><input id="serverNpc" type="checkbox" ${room.autoNpc?'checked':''}>服务端自动执行 NPC 回合</label><label>房间名<input id="renameRoom" maxlength="60" value="${esc(room.name)}"></label><button id="renameGo">保存房间名</button>`:''}<div class="button-row"><button id="copyMySeat">保留自己的席位凭据</button><button id="roomSettings">设置与存档</button></div><button id="leaveRoom" class="wide">返回房间入口 <span>→</span></button>`,'room');$('modalBody').querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>run('seat',{actor:b.dataset.claim,release:room.owners?.[b.dataset.claim]===seat.id}));$('modalBody').querySelectorAll('[data-assign]').forEach(b=>b.onchange=()=>run('seat',{actor:b.dataset.assign,seatId:b.value||undefined,release:!b.value}));$('copyMySeat').onclick=()=>modalCredential('自己的席位凭据',token);$('roomSettings').onclick=showSettings;$('leaveRoom').onclick=()=>{close();showLobby();};if(!owner)return;$('copyInvite').onclick=copyInvite;$('rotateInvite').onclick=()=>run('room',{rotateInvite:true});$('createAiSeat').onclick=showAiSeat;$('serverNpc').onchange=e=>run('room',{autoNpc:e.target.checked});$('renameGo').onclick=()=>run('room',{rename:$('renameRoom').value});$('pauseAi').onclick=()=>room.aiPaused?confirmResumeAI():run('ai/control',{action:'pause'});$('modalBody').querySelectorAll('[data-dm-seat]').forEach(b=>b.onclick=()=>run('room',{dmSeatId:b.dataset.dmSeat}));$('modalBody').querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>run('room',{removeSeatId:b.dataset.remove}));$('modalBody').querySelectorAll('[data-take]').forEach(b=>b.onclick=()=>run('ai/control',{action:'takeover',seatId:b.dataset.take}));$('modalBody').querySelectorAll('[data-api-run]').forEach(b=>b.onclick=()=>startApiSeat(b.dataset.apiRun));}
function modalCredential(title,value){modal(title,'<p>用于在另一台设备或工作区恢复这一席位。</p><input id="seatCredential" type="password" readonly autocomplete="off"><div class="button-row"><button id="copyCredential" class="primary">复制席位凭据</button><button id="credentialDone">完成</button></div>');$('seatCredential').value=value||'';$('copyCredential').onclick=()=>copyText(value||'','已复制此席位凭据');$('credentialDone').onclick=showRoom;}
function copyInvite(){if(!room?.invite)return toast('邀请链接由房主提供。');const url=new URL(location.href);url.search='';url.hash='invite='+encodeURIComponent(room.invite);copyText(url.href,'已复制邀请链接');}
function confirmResumeAI(){modal('恢复 API AI',`<p>恢复后，可按房主配置调用 ${esc(settings.model||'指定模型')}。模型服务可能收费；本次仅恢复权限，仍需点击请求或启动席位。</p><div class="button-row"><button id="resumeAiGo" class="primary">恢复 API AI</button><button id="resumeAiBack">保持暂停</button></div>`);$('resumeAiGo').onclick=async()=>{if(await run('ai/control',{action:'resume'}))showRoom();};$('resumeAiBack').onclick=showRoom;}
function startApiSeat(id){modal('启动 API 席位',`<p>调用 ${esc(settings.model||'房主配置的模型')}，按实际局面生成并采用合法回复。</p><label>本批最多调用次数<input id="apiSteps" type="number" min="1" max="100" value="3"></label><button id="apiStart" class="primary">恢复并启动本批次</button>`);$('apiStart').onclick=async()=>{if(await run('ai/control',{action:'resume',seatId:id,steps:Number($('apiSteps').value),autoApply:true}))showRoom();};}
function showAiSeat(){modal('新增 AI 席位',`<label>称呼<input id="aiSeatName" maxlength="40" value="AI 同行"></label><div class="form-grid"><label>接入方式<select id="aiSeatKind"><option value="workspace">工作区 AI</option><option value="api">API 模型</option></select></label><label>身份<select id="aiSeatRole"><option value="player">玩家</option><option value="dm">主持</option></select></label></div><label>领取角色<select id="aiSeatActor"><option value="">暂不领取</option>${party().map(a=>`<option value="${esc(a.id)}">${esc(a.name)}</option>`).join('')}</select></label><button id="aiSeatCreate" class="primary">建立席位</button>`);$('aiSeatCreate').onclick=async()=>{const value=await run('seats',{name:$('aiSeatName').value,kind:$('aiSeatKind').value,role:$('aiSeatRole').value,actors:$('aiSeatActor').value?[$('aiSeatActor').value]:[]});if(value)modalCredential('AI 席位已建立',value.createdSeatToken);};}
async function showSettings(){let slots=[];if(isDm())try{slots=await api('slots');}catch{}modal('设置与存档',`${isDm()?`<h3>房间存档</h3><div class="slot-grid">${[1,2,3].map(n=>{const info=slots.find(s=>s.slot===n);return `<div class="slot-card"><strong>手动槽 ${n}</strong><small>${info?.exists?'保存于 '+esc(new Date(info.saved).toLocaleString('zh-CN')):'尚未存档'}</small><div class="button-row"><button data-save-slot="${n}">保存</button><button data-load-slot="${n}" ${info?.exists?'':'disabled'}>读取</button></div></div>`;}).join('')}</div><div class="button-row"><button id="undoSave">撤销上一笔</button><button id="exportSave">导出战役</button><button id="importSave">导入战役</button><input id="saveFile" type="file" accept="application/json,.json" hidden><button id="newGame">重新开始</button></div><hr>`:'<p>每一步由服务端自动保存，刷新后可继续使用自己的席位。</p>'}${seat.isOwner?`<h3>API 接入</h3><p class="muted">${room.aiPaused?'已暂停':'已恢复'} · ${settings.hasKey?'已配置密钥':'尚未配置密钥'}</p><div class="form-grid"><label>协议<select id="cfgProtocol"><option value="responses">Responses</option><option value="chat">Chat Completions</option></select></label><label>模型 ID<input id="cfgModel" value="${esc(settings.model||'')}" autocomplete="off"></label><label class="full">服务基础地址<input id="cfgUrl" type="url" value="${esc(settings.baseUrl||'https://api.openai.com/v1')}" autocomplete="off"></label><label class="full">API 密钥<input id="cfgKey" type="password" autocomplete="off" placeholder="${settings.hasKey?'留空保留已配置密钥':'尚未配置'}"></label></div><div class="button-row"><button id="cfgSave" class="primary">保存接入设置</button><button id="cfgClear">清除密钥</button><button id="cfgPause">${room.aiPaused?'恢复 API AI':'暂停全部 AI'}</button></div>`:''}`);if(isDm()){$('modalBody').querySelectorAll('[data-save-slot]').forEach(b=>b.onclick=async()=>{if(await run('slot',{slot:+b.dataset.saveSlot}))showSettings();});$('modalBody').querySelectorAll('[data-load-slot]').forEach(b=>b.onclick=async()=>{if(await run('slot',{slot:+b.dataset.loadSlot,load:true}))close();});$('undoSave').onclick=()=>run('undo');$('exportSave').onclick=async()=>{try{download('雅法余烬-战役.json',JSON.stringify(await api('save'),null,2));}catch(e){toast(e.message);}};$('importSave').onclick=()=>$('saveFile').click();$('saveFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>3*1024*1024)throw Error('存档超过3MB。');if(await run('import',{save:JSON.parse(await file.text())}))close();}catch(e){toast('导入失败：'+e.message);}};$('newGame').onclick=()=>{modal('重新开始这一桌','<p>将当前战役重置为第一景。可先保存到手动槽，或使用撤销恢复。</p><button id="newGo" class="primary">重置本桌战役</button>');$('newGo').onclick=async()=>{if(await run('new'))close();};};}if(seat.isOwner){$('cfgProtocol').value=settings.protocol||'responses';$('cfgSave').onclick=async()=>{if(await run('config',{protocol:$('cfgProtocol').value,model:$('cfgModel').value.trim(),baseUrl:$('cfgUrl').value.trim(),key:$('cfgKey').value.trim()})){$('cfgKey').value='';toast('接入设置已保存');}};$('cfgClear').onclick=async()=>{if(await run('config',{clearKey:true}))showSettings();};$('cfgPause').onclick=()=>room.aiPaused?confirmResumeAI():run('ai/control',{action:'pause'});}}
function showGM(id=selected){if(!isDm())return;const a=state.actors.find(a=>a.id===id)||unit();const numberFields=[['hp','当前 HP'],['maxHp','最大 HP'],['ac','AC'],['speed','速度（尺）'],['potions','治疗药水'],['action','本回合动作'],['bonus','本回合附赠'],['move','剩余移动'],['hd','生命骰'],['wind','回气'],['surge','动作如潮'],['channel','引导神力'],['arcane','奥术回想'],['tempHp','临时 HP']];modal('主持裁定',`<label>角色<select id="gmActor">${state.actors.map(t=>`<option value="${esc(t.id)}" ${t.id===a.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><div class="form-grid">${numberFields.map(([k,n])=>`<label>${n}<input id="gm-${k}" type="number" min="0" max="1000" value="${a[k]??0}"></label>`).join('')}<label>位置 X（尺）<input id="gm-x" type="number" step=".5" value="${a.x}"></label><label>位置 Y（尺）<input id="gm-y" type="number" step=".5" value="${a.y}"></label><label class="full">状态（中文逗号分隔）<input id="gm-conditions" value="${esc((a.conditions||[]).join('，'))}"></label><label class="full">裁定原因<textarea id="gmReason" rows="3" required></textarea></label></div><div class="button-row"><button id="gmApply" class="primary">写入裁定</button><button id="gmEnd">结束遭遇 / 接受投降</button></div><details><summary>完整卡片字段</summary><textarea id="gmCard" rows="9">${esc(JSON.stringify({abilities:a.abilities,slots:a.slots||[],maxSlots:a.maxSlots||[],attacks:a.attacks||1,weapons:a.weapons},null,2))}</textarea></details><details><summary>物品、事实与场景裁定</summary><p class="muted">支持 item / gold / fact / npc / status / attitude / itemOwner / holder / promise / chapter / hours。</p><textarea id="gmPatch" rows="6" placeholder='{"fact":{"example":true}}'></textarea><button id="gmPatchGo">写入额外裁定</button></details><details><summary>导入玩家 / NPC 战斗卡</summary><textarea id="npcJson" rows="8" placeholder='{"name":"临时角色","side":"enemy","ac":12,"maxHp":11,"speed":30,"x":2.5,"y":2.5,"abilities":[11,12,12,10,10,10],"weapons":[{"name":"短剑","bonus":3,"dice":"1d6","damageBonus":1,"range":5,"long":5,"type":"piercing"}]}'></textarea><button id="npcAdd">导入卡片</button></details>`);$('gmActor').onchange=e=>showGM(e.target.value);const applyPatch=async patch=>{const reason=$('gmReason').value.trim();if(!reason)return toast('请填写本次裁定原因。');if(await cmd({type:'gm',actor:selected,text:reason,patch}))showGM(a.id);};$('gmApply').onclick=()=>{try{const patch={actor:a.id,conditions:$('gm-conditions').value,position:{x:Number($('gm-x').value),y:Number($('gm-y').value)},card:JSON.parse($('gmCard').value)};for(const [k]of numberFields)patch[k]=Number($('gm-'+k).value);applyPatch(patch);}catch(e){toast('卡片 JSON 格式无效：'+e.message);}};$('gmEnd').onclick=()=>applyPatch({endCombat:true});$('gmPatchGo').onclick=()=>{try{applyPatch(JSON.parse($('gmPatch').value));}catch(e){toast('裁定 JSON 格式无效：'+e.message);}};$('npcAdd').onclick=()=>{try{applyPatch({add:JSON.parse($('npcJson').value)});}catch(e){toast('角色 JSON 格式无效：'+e.message);}};}
function aiActor(){const targetSeat=room.seats.find(s=>s.id===$('aiTarget')?.value)||seat;return targetSeat.role==='dm'||targetSeat.id===room.ownerId?selected:targetSeat.actors?.includes(selected)?selected:targetSeat.actors?.[0];}
function showAI(){const members=isDm()?room.seats:room.seats.filter(s=>s.id===seat.id);modal('AI 同行',`<div class="ai-panel"><div class="form-grid"><label>席位<select id="aiTarget">${members.map(s=>`<option value="${esc(s.id)}" ${s.id===seat.id?'selected':''}>${esc(s.name)} · ${s.role==='dm'?'主持':'玩家'}</option>`).join('')}</select></label><label>接入<select id="aiMode"><option value="bridge">工作区 AI · 复制与导入</option><option value="api">API 模型</option></select></label></div><p id="aiStatus" class="muted"></p><label>这一次想做什么<textarea id="aiText" rows="3" maxlength="5000" placeholder="回应当前情形，或处理本角色的下一步行动"></textarea></label><div class="button-row"><button id="askAI" class="primary">创建工作区请求</button><button id="copyRequest">复制当前请求</button><button id="pasteAI">导入回复</button></div><div id="aiResult" class="ai-result"></div></div>`,'ai');const update=()=>{if(!$('aiMode')||!$('aiStatus'))return;$('aiStatus').textContent=$('aiMode').value==='api'?(room.aiPaused?'API AI 已暂停；房主可在房间中恢复。':(settings.hasKey?'按已配置模型发起真实调用。':'尚未配置 API 密钥。')):'把请求交给你的工作区 AI，返回后导入结构化回复。';$('askAI').textContent=aiBusy?'AI 正在思考…':$('aiMode').value==='api'?'调用 API 模型':'创建工作区请求';$('askAI').disabled=aiBusy||($('aiMode').value==='api'&&(room.aiPaused||!settings.hasKey));};$('aiMode').onchange=update;$('aiTarget').onchange=()=>{requestCache=null;};$('askAI').onclick=async()=>{const value=await run('ai/request',{seatId:$('aiTarget').value,actor:aiActor(),mode:$('aiMode').value,text:$('aiText').value});if(value)requestCache=value.request;update();renderAiResult();};$('copyRequest').onclick=async()=>{try{const seatId=$('aiTarget').value;if(!requestCache||requestCache.revision!==state.revision||pending?.id!==requestCache.id||requestCache.seat?.id!==seatId){const value=await run('ai/request',{seatId,actor:aiActor(),mode:'bridge',text:$('aiText').value});if(!value)return;requestCache=value.request;}if(!requestCache){const value=await api('bridge/request');requestCache=value.request;}if(requestCache)await copyText(JSON.stringify(requestCache,null,2),'已复制当前局面与回复格式');}catch(e){toast(e.message);}};$('pasteAI').onclick=()=>{if(!pending)return toast('请先创建当前局面的 AI 请求。');const id=pending.id;modal('导入 AI 回复','<label>结构化回复<textarea id="aiPaste" rows="10" placeholder=\'{"narration":"…","actionIndex":null,"reason":"…"}\'></textarea></label><button id="aiPasteGo" class="primary">读取建议</button>');$('aiPasteGo').onclick=async()=>{if(await run('ai/response',{id,response:$('aiPaste').value}))showAI();};};update();renderAiResult();}
function renderAiResult(){if(!$('aiResult'))return;const result=pending?.result,stale=pending?.stale||pending?.revision!==state.revision;$('aiResult').innerHTML=pending?.error?`<p>${esc(pending.error)}</p>`:result?`<p>${esc(result.narration||'')}</p>${result.reason?`<p class="muted">${esc(result.reason)}</p>`:''}<p>提议：${esc(pending.action?.label||pending.action?.text||pending.action?.type||'仅叙事')}</p><button id="applyAI" class="primary" ${stale?'disabled':''}>${stale?'局面已更新，请重新请求':'采用回复'}</button>`:pending?'<p>'+ (aiBusy?'AI 正在思考…':'等待工作区回复。')+'</p>':'<p>暂无待处理的 AI 回复。</p>';if(seat.isOwner&&(pending||aiBusy))$('aiResult').innerHTML+='<div class="button-row"><button id="cancelAI">停止并暂停 AI</button></div>';if($('applyAI'))$('applyAI').onclick=()=>run('ai/apply',{id:pending.id});if($('cancelAI'))$('cancelAI').onclick=()=>run('ai/control',{action:'cancel'});}
function saveSession(value){token=value.token;room=value.room;seat=value.seat;const saved={token,roomId:room.id,name:room.name,seatName:seat.name};saveStored(sessionKey,saved);const previous=stored(sessionKey+'-all',[]);saveStored(sessionKey+'-all',[saved,...(Array.isArray(previous)?previous:[]).filter(s=>s.roomId!==room.id)].slice(0,8));}
function showLobby(){streamGeneration++;stream?.abort();stream=null;document.body.classList.add('in-lobby');document.body.classList.remove('side-open');$('lobby').hidden=false;$('gameShell').hidden=true;$('resumeRoom').hidden=!stored(sessionKey);const saved=stored(sessionKey+'-all',[]);$('savedRooms').innerHTML=Array.isArray(saved)&&saved.length>1?saved.map((s,i)=>`<button data-saved="${i}">${esc(s.name||'盐仓之夜')} · ${esc(s.seatName||'席位')}</button>`).join(''):'';$('savedRooms').querySelectorAll('button').forEach(b=>b.onclick=()=>{saveStored(sessionKey,saved[+b.dataset.saved]);resume();});}
async function enter(value,prepare=false){if(activeRoomId!==value.room.id){state=null;eventSeq=0;actions=[];tiles=[];pending=null;target=null;requestCache=null;activeRoomId=value.room.id;}if(value.token)saveSession(value);$('lobby').hidden=true;$('gameShell').hidden=false;document.body.classList.remove('in-lobby','side-open');await absorb(value);await loadActions();board.reset();connection(true);connectEvents();if(prepare)showRoom();}
async function resume(){const saved=stored(sessionKey);if(!saved?.token)return;token=saved.token;room={id:saved.roomId};try{await enter(await api('state'));}catch(e){showLobby();toast('席位恢复失败：'+e.message);}}
async function connectEvents(){stream?.abort();const generation=++streamGeneration;let failures=0,delay=1000;while(generation===streamGeneration&&!$('gameShell').hidden){stream=new AbortController();try{const response=await fetch('/api/events?since='+eventSeq,{headers:{'X-Seat-Token':token,'X-Room-Id':room.id},signal:stream.signal,cache:'no-store'});if(!response.ok||!response.body)throw Error('实时连接中断');connection(true);const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';for(;;){const chunk=await reader.read();if(chunk.done)break;buffer+=decoder.decode(chunk.value,{stream:true}).replaceAll('\r\n','\n');let cut;while((cut=buffer.indexOf('\n\n'))>=0){const frame=buffer.slice(0,cut);buffer=buffer.slice(cut+2);const payload=frame.split('\n').filter(line=>line.startsWith('data:')).map(line=>line.slice(5).trimStart()).join('\n');if(payload&&generation===streamGeneration){await absorb(JSON.parse(payload));connection(true);}}}}catch(e){if(generation!==streamGeneration)return;connection(false);}if(generation!==streamGeneration)return;if(++failures>=2){pollUpdates(generation);return;}await new Promise(resolve=>setTimeout(resolve,delay));delay=Math.min(delay*2,10000);}}
async function pollUpdates(generation){stream?.abort();stream=new AbortController();let interval=2000;while(generation===streamGeneration&&!$('gameShell').hidden){try{const signal=AbortSignal.any([stream.signal,AbortSignal.timeout(12000)]);const value=await api('updates?since='+eventSeq,undefined,signal);if(generation!==streamGeneration)return;await absorb(value);connection(true,'已连接 · 同步');interval=2000;}catch(e){if(generation!==streamGeneration)return;connection(false);interval=Math.min(interval*2,15000);}await new Promise(resolve=>setTimeout(resolve,interval));}}
async function entrySubmit(e,route,body){e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;$('lobbyError').textContent='';try{await enter(await api(route,body),true);history.replaceState(null,'',location.pathname);}catch(e){toast(e.message);}finally{button.disabled=false;}}
function entryTab(join){$('createRoom').hidden=join;$('joinRoom').hidden=!join;$('createTab').classList.toggle('active',!join);$('joinTab').classList.toggle('active',join);$('lobbyError').textContent='';}
$('createTab').onclick=()=>entryTab(false);$('joinTab').onclick=()=>entryTab(true);
$('createRoom').onsubmit=e=>entrySubmit(e,'rooms',{name:$('roomName').value.trim(),displayName:$('hostName').value.trim()});
$('joinRoom').onsubmit=e=>{let invite=$('inviteCode').value.trim();try{if(invite.includes('://')){const url=new URL(invite);invite=new URLSearchParams(url.hash.slice(1)).get('invite')||url.searchParams.get('invite')||invite;}}catch{}entrySubmit(e,'join',{invite,displayName:$('playerName').value.trim()});};
$('resumeRoom').onclick=resume;$('returnLobby').onclick=showLobby;$('roomBtn').onclick=showRoom;
const workshopButton=document.createElement('button');workshopButton.id='workshopBtn';workshopButton.textContent='地图工坊';workshopButton.onclick=()=>{if(!isDm()){toast('地图制作需要主持人或房主权限。');return;}sessionStorage.setItem('map-workshop-seat',JSON.stringify({token,roomId:room.id,returnPath:location.pathname}));location.href='/cartography.html?scene='+encodeURIComponent(state.scene);};$('roomBtn').after(workshopButton);$('inviteBtn').onclick=copyInvite;$('settingsBtn').onclick=showSettings;$('journalBtn').onclick=()=>showJournal();$('bookBtn').onclick=()=>showBook();$('gmBtn').onclick=()=>showGM();$('mapInfoBtn').onclick=()=>showDoors();$('aiNav').onclick=showAI;
$('closeModal').onclick=close;$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
$('closeSide').onclick=()=>{document.body.classList.remove('side-open');document.querySelectorAll('[data-mobile]').forEach(b=>b.classList.toggle('active',b.dataset.mobile==='map'));};
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>setSide(b.dataset.tab));document.querySelectorAll('[data-mobile]').forEach(b=>b.onclick=()=>{if(b.dataset.mobile==='map'){$('closeSide').click();return;}setSide(b.dataset.mobile);});
document.querySelectorAll('[data-log]').forEach(b=>b.onclick=()=>{logTab=b.dataset.log;document.querySelectorAll('[data-log]').forEach(el=>el.classList.toggle('active',el===b));renderLog();});
$('chatForm').onsubmit=async e=>{e.preventDefault();const text=$('chatText').value.trim();if(text&&await cmd({type:'chat',text}))$('chatText').value='';};
$('rollBtn').onclick=()=>cmd({type:'roll',actor:owns(selected)?selected:undefined,text:$('diceInput').value.trim()});$('diceInput').addEventListener('keydown',e=>{if(e.key==='Enter')$('rollBtn').click();});$('undoBtn').onclick=()=>run('undo');
function syncCameraControls(){for(const [id,on]of[['gridBtn',board.grid],['wallBtn',board.low],['topView',board.pitch>1.5],['panMap',board.gestureMode==='pan']]){$(id)?.classList.toggle('active',on);$(id)?.setAttribute('aria-pressed',String(on));}}
