$('zoomIn').onclick=()=>board.zoomBy(1.18);$('zoomOut').onclick=()=>board.zoomBy(1/1.18);$('resetMap').onclick=()=>{board.reset();syncCameraControls();};$('gridBtn').onclick=()=>{board.grid=!board.grid;board.draw();syncCameraControls();};
$('rotateLeft').onclick=()=>board.rotate(-Math.PI/8);$('rotateRight').onclick=()=>board.rotate(Math.PI/8);$('tiltUp').onclick=()=>board.rotate(0,.13);$('tiltDown').onclick=()=>board.rotate(0,-.13);$('topView').onclick=()=>{board.topView();syncCameraControls();};$('wallBtn').onclick=()=>{board.setLow(!board.low);syncCameraControls();};$('panMap').onclick=()=>{board.gestureMode=board.gestureMode==='pan'?'rotate':'pan';syncCameraControls();};$('exportMesh').onclick=()=>{if(!state)return;download(state.scene+'-雅法沙盘.obj',board.exportOBJ(),'text/plain;charset=utf-8');toast('已导出完整高度沙盘 · 1 OBJ单位 = 1尺');};
$('restoreSeat').onclick=()=>{modal('恢复自己的席位','<label>席位凭据<input id="restoreToken" type="password" autocomplete="off" required></label><button id="restoreGo" class="primary">恢复席位</button>');$('restoreGo').onclick=async()=>{const candidate=$('restoreToken').value.trim();if(!candidate)return;const oldToken=token,oldRoom=room;token=candidate;room=null;try{const value=await api('state');value.token=candidate;close();await enter(value);}catch(e){token=oldToken;room=oldRoom;toast(e.message);}};};
document.addEventListener('keydown',e=>{if($('modal').open||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||!state||$('gameShell').hidden)return;if(['1','2','3','4'].includes(e.key)){const a=party()[+e.key-1];if(a)selectActor(a.id);}if(e.key==='Escape'){target=null;mode='move';render();document.body.classList.remove('side-open');}if(e.code==='Space'&&state.combat&&owns(state.current)){e.preventDefault();cmd({type:'end',actor:state.current});}});
