const initialInvite=new URLSearchParams(location.hash.slice(1)).get('invite')||new URLSearchParams(location.search).get('invite');if(initialInvite){entryTab(true);$('inviteCode').value=initialInvite;}
showLobby();

const lanButton=document.createElement('button');lanButton.textContent='同网邀请';lanButton.onclick=async()=>{if(!seat?.isOwner){toast('请让房主生成同网邀请。');return;}try{const n=await api('network');modal('同网邀请',`<p>${esc(n.message)}</p>${n.addresses.length?'<label>将下面的完整邀请发给同网朋友<textarea id="lanLinks" readonly rows="5">'+esc(n.addresses.map(url=>url+'/#invite='+room.invite).join('\n'))+'</textarea></label>':'<p>使用本游戏目录的「启动局域网.cmd」，再在此查看入口。127.0.0.1链接只在房主电脑有效。</p>'}`);if($('lanLinks'))$('lanLinks').onclick=()=> $('lanLinks').select();}catch(e){toast(e.message);}};$('roomBtn').after(lanButton);
